(()=>{const hero=document.getElementById('hero');const slides=[...hero.querySelectorAll('.slide')];const choices=[...hero.querySelectorAll('.slide-choice')];const videos=slides.map(slide=>slide.querySelector('video'));const playButton=document.getElementById('playButton');const announcement=document.getElementById('slideAnnouncement');const reduceMotion=matchMedia('(prefers-reduced-motion: reduce)');let current=0;let pageActive=parent===window;let userPaused=reduceMotion.matches;let focusPaused=false;let pointerStart=null;let generation=0;function progress(){const video=videos[current];const fraction=Number.isFinite(video.duration)&&video.duration>0?video.currentTime/video.duration:0;choices[current].style.setProperty('--video-progress',`${Math.min(1, fraction) * 100}%`);}
function sync(){const active=videos[current];const shouldPlay=pageActive&&!document.hidden&&!userPaused&&!focusPaused;hero.classList.toggle('is-paused',!shouldPlay);playButton.setAttribute('aria-pressed',String(userPaused));playButton.setAttribute('aria-label',userPaused?'Play hero video':'Pause hero video');playButton.querySelector('span').textContent=userPaused?'▶':'Ⅱ';videos.forEach(video=>{if(video!==active||!shouldPlay)video.pause();});if(shouldPlay&&active.paused&&!active.error){const token=generation;active.play().catch(error=>{if(token!==generation||error.name==='AbortError')return;userPaused=true;sync();});}
progress();}
function show(index,announce=true){const next=(index+slides.length)%slides.length;generation+=1;videos[current].pause();current=next;hero.dataset.slide=String(current);slides.forEach((slide,i)=>{const active=i===current;slide.classList.toggle('active',active);slide.toggleAttribute('inert',!active);if(active)slide.removeAttribute('aria-hidden');else slide.setAttribute('aria-hidden','true');choices[i].classList.toggle('active',active);choices[i].style.setProperty('--video-progress','0%');if(active)choices[i].setAttribute('aria-current','true');else choices[i].removeAttribute('aria-current');});videos[current].currentTime=0;if(announce)announcement.textContent=slides[current].getAttribute('aria-label');sync();}
videos.forEach((video,index)=>{video.muted=true;video.loop=false;video.addEventListener('ended',()=>{if(index===current&&pageActive&&!document.hidden&&!userPaused&&!focusPaused)show(current+1,false);});video.addEventListener('timeupdate',()=>{if(index===current)progress();});video.addEventListener('loadedmetadata',()=>{if(index===current)sync();});video.addEventListener('error',()=>{if(index===current){userPaused=true;sync();}});});document.getElementById('previous').addEventListener('click',()=>show(current-1));document.getElementById('next').addEventListener('click',()=>show(current+1));choices.forEach((choice,index)=>choice.addEventListener('click',()=>show(index)));playButton.addEventListener('click',()=>{userPaused=!userPaused;if(!userPaused&&videos[current].ended)videos[current].currentTime=0;sync();});hero.addEventListener('focusin',()=>{focusPaused=document.activeElement!==playButton&&document.activeElement.matches(':focus-visible');sync();});hero.addEventListener('focusout',()=>setTimeout(()=>{focusPaused=hero.contains(document.activeElement)&&document.activeElement!==playButton&&document.activeElement.matches(':focus-visible');sync();},0));hero.addEventListener('keydown',event=>{if(event.key==='ArrowRight'||event.key==='ArrowLeft'){event.preventDefault();show(current+(event.key==='ArrowRight'?1:-1));}});hero.addEventListener('pointerdown',event=>{if(event.pointerType==='touch')pointerStart=event.clientX;});hero.addEventListener('pointercancel',()=>{pointerStart=null;});hero.addEventListener('pointerup',event=>{if(pointerStart===null)return;const distance=event.clientX-pointerStart;pointerStart=null;if(Math.abs(distance)>50)show(current+(distance<0?1:-1));});document.querySelectorAll('.explore-button').forEach(button=>button.addEventListener('click',()=>{parent.postMessage({namespace:'ctuav-demo',type:'route',route:button.dataset.route},'*');}));document.addEventListener('visibilitychange',sync);reduceMotion.addEventListener('change',event=>{userPaused=event.matches;sync();});addEventListener('message',event=>{if(event.source!==parent||event.data?.namespace!=='ctuav-demo')return;if(event.data.type==='palette'){const theme=event.data.theme==='night'?'night':'mono';document.documentElement.dataset.theme=theme;hero.dataset.theme=theme;}
if(event.data.type==='view-active'){pageActive=!!event.data.active;sync();}});sync();})();